const tabId = 1962625075;
const i140Info = await browserjs(tabId, () => {
  // Find button or element with text "I-140, Immigrant Petition for Alien Workers"
  const btns = Array.from(document.querySelectorAll('button, a, h2, h3, div'));
  const target = btns.find(el => el.textContent?.trim() === 'I-140, Immigrant Petition for Alien Workers');
  if (!target) return 'Not found';
  return {
    tagName: target.tagName,
    className: target.className,
    id: target.id,
    parentText: target.parentElement?.innerHTML?.slice(0, 1000)
  };
});
console.log(JSON.stringify(i140Info, null, 2));

const tabId = 1962625075;
const result = await browserjs(tabId, () => {
  const main = document.querySelector('main') || document.body;
  // find all elements in main mentioning I-140
  const walker = document.createTreeWalker(main, NodeFilter.SHOW_TEXT);
  const hits = [];
  let node;
  while (node = walker.nextNode()) {
    if (node.textContent.includes('I-140')) {
      hits.push({
        text: node.textContent.trim(),
        parentTag: node.parentElement?.tagName,
        parentClass: node.parentElement?.className,
        grandparentText: node.parentElement?.parentElement?.textContent?.slice(0, 300)
      });
    }
  }
  return hits;
});
console.log(JSON.stringify(result, null, 2));

